model_dict = {'X_train': [gbr, gbr_gs, rfr, rfr_gs],
              'X_2_train': [gbr2, rfr2]}

for key in model_dict:
    f_list = []
    fearture_names = X_train.columns.tolist() if key == 'X_train' else X_2_train.columns.tolist()
    f_index = ['gbr', 'gbr_gs', 'rfr', 'rfr_gs'] if key == 'X_train' else ['gbr2', 'rfr2']

    for model in model_dict[key]:
        feature_importance = np.asarray(model.feature_importances_)
        # Align feature importance length with current feature set to avoid shape issues
        if len(feature_importance) != len(fearture_names):
            if len(feature_importance) < len(fearture_names):
                feature_importance = np.pad(feature_importance, (0, len(fearture_names) - len(feature_importance)), mode='constant')
            else:
                feature_importance = feature_importance[:len(fearture_names)]
        f_list.append(feature_importance)

    feature_df = pd.DataFrame(f_list, columns=fearture_names, index=f_index)
    display(feature_df)

